import{_ as o,o as r,c as n,a2 as a}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"2.1 电工基本概念","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-1-dian-gong-ji-ben-gai-nian.md","filePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-1-dian-gong-ji-ben-gai-nian.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-1-dian-gong-ji-ben-gai-nian.md"};function i(e,t,s,d,g,u){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_2-1-电工基本概念" tabindex="-1">2.1 电工基本概念 <a class="header-anchor" href="#_2-1-电工基本概念" aria-label="Permalink to &quot;2.1 电工基本概念&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>这一节是&quot;电工的地基中的地基&quot;:<strong>电到底是个什么东西?电流、电压、电阻各是什么?</strong> 很多没学过电的人会觉得这些概念很抽象,所以这一节全部用&quot;水流&quot;来打比方——把看不见的电,想象成看得见的水。</p><h2 id="一、电从哪里来-电荷与电子" tabindex="-1">一、电从哪里来:电荷与电子 <a class="header-anchor" href="#一、电从哪里来-电荷与电子" aria-label="Permalink to &quot;一、电从哪里来:电荷与电子&quot;">​</a></h2><p><strong>电荷</strong>是物质的一种基本属性,分两种:</p><ul><li><strong>正电荷</strong>(用 <code>+</code> 表示):质子带的电荷;</li><li><strong>负电荷</strong>(用 <code>−</code> 表示):电子带的电荷。</li></ul><p>规则一句话记住:<strong>同种电荷相斥,异种电荷相吸。</strong></p><p>我们平时说的&quot;静电&quot;(比如冬天摸门把手被&quot;电&quot;一下),其实是因为物体摩擦时<strong>电子发生了转移</strong>——摩擦起电就是电荷的重新分配,而不是&quot;造出了电&quot;。</p><h2 id="二、电流-电荷的-定向移动" tabindex="-1">二、电流:电荷的&quot;定向移动&quot; <a class="header-anchor" href="#二、电流-电荷的-定向移动" aria-label="Permalink to &quot;二、电流:电荷的&quot;定向移动&quot;&quot;">​</a></h2><p><strong>电流</strong>,是指<strong>电荷有规则(定向)地移动</strong>形成的。</p><ul><li>电流方向,规定为<strong>正电荷移动的方向</strong>(从高电位流向低电位)。</li><li>但实际上,金属导线里真正移动的是<strong>电子</strong>,电子带负电,所以电子移动方向与电流方向<strong>相反</strong>——这个易混点考试常考。</li><li>电流用字母 <strong>I</strong> 表示,单位是<strong>安培(A)</strong>,常用单位还有 <strong>mA(毫安)、μA(微安)</strong>。 <ul><li><code>1 A = 1000 mA</code>,<code>1 mA = 1000 μA</code></li></ul></li></ul><p><strong>电流的三种效应</strong>(判断电路中有无电流的根据):</p><table tabindex="0"><thead><tr><th>效应</th><th>表现</th><th>应用举例</th></tr></thead><tbody><tr><td>热效应</td><td>电流通过导体发热</td><td>电炉、白炽灯</td></tr><tr><td>磁效应</td><td>电流周围产生磁场</td><td>电磁铁、继电器</td></tr><tr><td>化学效应</td><td>电流引起化学反应</td><td>电镀、充电</td></tr></tbody></table><blockquote><p>💡 <strong>水流类比</strong>:电流就像水管里流动的水。水管里没有水在流,就没有&quot;水流&quot;;导线上没有电荷在动,就没有电流。</p></blockquote><h2 id="三、电压-推动电流的-水压" tabindex="-1">三、电压:推动电流的&quot;水压&quot; <a class="header-anchor" href="#三、电压-推动电流的-水压" aria-label="Permalink to &quot;三、电压:推动电流的&quot;水压&quot;&quot;">​</a></h2><p><strong>电压</strong>,是使电荷定向移动形成电流的<strong>推动力</strong>。它表示两点之间的电位差,俗称&quot;电势差&quot;。</p><ul><li>电压用字母 <strong>U</strong> 表示,单位是<strong>伏特(V)</strong>,常用单位还有 <strong>kV(千伏)、mV(毫伏)</strong>。 <ul><li><code>1 kV = 1000 V</code>,<code>1 V = 1000 mV</code></li></ul></li><li><strong>电动势(E)</strong>:电源内部&quot;产生电压&quot;的能力,比如电池的电动势。</li></ul><blockquote><p>💡 <strong>水流类比</strong>:水从高处流向低处,靠的是&quot;水位差&quot;(水压)。电流从高电位流向低电位,靠的就是&quot;电压&quot;。<strong>没有水位差,水不流;没有电压,电流不流。</strong></p></blockquote><p>为什么电压越高越危险?后面第 3 章会讲——因为电压是&quot;推动力&quot;,推动力越大,同样的电阻下电流就越大。</p><h2 id="四、电阻-电流的-阻力" tabindex="-1">四、电阻:电流的&quot;阻力&quot; <a class="header-anchor" href="#四、电阻-电流的-阻力" aria-label="Permalink to &quot;四、电阻:电流的&quot;阻力&quot;&quot;">​</a></h2><p><strong>电阻</strong>,是导体对电流的<strong>阻碍作用</strong>。</p><ul><li>电阻用字母 <strong>R</strong> 表示,单位是<strong>欧姆(Ω)</strong>,常用单位还有 <strong>kΩ(千欧)、MΩ(兆欧)</strong>。 <ul><li><code>1 kΩ = 1000 Ω</code>,<code>1 MΩ = 1000 kΩ = 10⁶ Ω</code></li></ul></li></ul><p><strong>电阻定律</strong>(决定电阻大小的因素):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>R = ρ · L / S</span></span></code></pre></div><ul><li><strong>ρ(ρ,读音 ro)</strong>:电阻率,反映材料本身的性质;</li><li><strong>L</strong>:导体长度;</li><li><strong>S</strong>:导体横截面积。</li></ul><p>一句话记:<strong>材料、长度、粗细</strong>决定电阻大小——同样的材料,线越长电阻越大、线越粗电阻越小。</p><blockquote><p>💡 <strong>水流类比</strong>:电阻就像水管里的&quot;砂石&quot;或管子的粗细。管子越细越长,水越难通过;导体电阻越大,电流越难通过。导体的电阻跟温度也有关系,一般金属导体温度升高,电阻增大。</p></blockquote><h2 id="五、导体、绝缘体、半导体" tabindex="-1">五、导体、绝缘体、半导体 <a class="header-anchor" href="#五、导体、绝缘体、半导体" aria-label="Permalink to &quot;五、导体、绝缘体、半导体&quot;">​</a></h2><p>按导电能力,材料分三类:</p><table tabindex="0"><thead><tr><th>类别</th><th>特点</th><th>例子</th></tr></thead><tbody><tr><td><strong>导体</strong></td><td>容易导电</td><td>铜、铝、铁等金属,人体(湿手时导电更强)</td></tr><tr><td><strong>绝缘体</strong></td><td>不容易导电</td><td>橡胶、塑料、玻璃、干燥木材</td></tr><tr><td><strong>半导体</strong></td><td>导电能力介于导体与绝缘体之间</td><td>硅、锗,用于二极管、晶体管</td></tr></tbody></table><blockquote><p>⚠️ <strong>注意</strong>:导体和绝缘体<strong>没有绝对界限</strong>。绝缘体在电压过高、潮湿、老化、破损时会变成导体(比如湿木头、老化的电线外皮)——这正是&quot;绝缘并不是永远安全&quot;的原因。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 电流方向规定为正电荷移动方向,<strong>电子移动方向与电流方向相反</strong>。</li><li>✅ 电流三大效应:热效应、磁效应、化学效应。</li><li>✅ 电阻定律 <code>R = ρL/S</code>:长度长则电阻大,截面积大则电阻小。</li><li>✅ 导体/绝缘体无绝对界限,潮湿、老化会降低绝缘性能。</li><li>⚠️ 易混点:电压是&quot;原因&quot;(推动力),电流是&quot;结果&quot;(电荷流动),先有电压才可能有电流。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>电流 = 电荷定向移动,单位 A;电压 = 推动电荷的电位差,单位 V;电阻 = 阻碍电流,单位 Ω。</li><li>三个概念用&quot;水流&quot;理解:<strong>水压(电压)→ 水流(电流)→ 阻力(电阻)</strong>。</li><li>导体易导电、绝缘体难导电、半导体介于之间。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)电流方向就是电子运动的方向。( )</li><li>(单选)电流的单位是(),电压的单位是(),电阻的单位是()。 A. V、A、Ω　B. A、V、Ω　C. Ω、V、A　D. A、Ω、V</li><li>(判断)同种电荷相互吸引,异种电荷相互排斥。( )</li><li>(单选)在相同材料下,电阻与导体长度的关系是()。 A. 长度越长电阻越大　B. 长度越长电阻越小　C. 无关　D. 成反比</li><li>(判断)绝缘体在任何情况下都不会导电。( )</li><li>(单选)下列不属于电流效应的是()。 A. 热效应　B. 磁效应　C. 重力效应　D. 化学效应</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>×</strong>。电流方向规定为正电荷移动方向,而电子带负电,移动方向与电流方向相反。</li><li><strong>B</strong>。电流 A、电压 V、电阻 Ω。</li><li><strong>×</strong>。同种电荷相斥、异种电荷相吸。</li><li><strong>A</strong>。电阻与长度成正比、与截面积成反比(R = ρL/S)。</li><li><strong>×</strong>。绝缘体在电压过高、潮湿、老化、破损等情况下可能变成导体。</li><li><strong>C</strong>。电流的效应是热效应、磁效应、化学效应,没有&quot;重力效应&quot;。</li></ol></details>',38)])])}const q=o(l,[["render",i]]);export{c as __pageData,q as default};
